import core from "./studio-api-journal.mjs";
import {applyNatureBrand} from "./studio-nature-theme.mjs";
import {STUDIO_JS as OLD} from "./studio-client-v6.mjs";
import {STUDIO_JS as NEW} from "./studio-client-nature-v131-release.mjs";
import {STUDIO_EDITORIAL_CSS} from "./studio-editorial-css-v130.mjs";
import {STUDIO_NATURE_CSS_V131} from "./studio-nature-css-v131.mjs";
import {exportBundle} from "./studio-docx-export.mjs";
const json=(obj,status=200)=>Response.json(obj,{status,headers:{"Cache-Control":"private,no-store"}});
const toHex=bytes=>Array.from(new Uint8Array(bytes),v=>v.toString(16).padStart(2,"0")).join("");
async function account(req,env) {
 const match=(req.headers.get("cookie")||"").match(/(?:^|;\s*)ht_blog_session=([0-9a-f]{64})/);
 if(!match)return null;
 const hash=toHex(await crypto.subtle.digest("SHA-256",new TextEncoder().encode(match[1])));
 return env.DB.prepare("SELECT u.id,u.role FROM users u JOIN sessions s ON s.user_id=u.id WHERE s.token_hash=? AND s.expires_at>datetime('now')").bind(hash).first();
}
async function readership(env) {
 const [a,b,top]=await Promise.all([
 env.DB.prepare("SELECT day,SUM(views) views FROM post_daily_views WHERE day>=date('now','-89 days') GROUP BY day").all(),
 env.DB.prepare("SELECT day,SUM(views) views FROM post_daily_view_sources WHERE source='nature' AND day>=date('now','-89 days') GROUP BY day").all(),
 env.DB.prepare("SELECT p.id,p.locale,p.slug,p.title,COALESCE(x.n,0) nature,COALESCE(y.n,0) studio FROM posts p LEFT JOIN (SELECT post_id,SUM(views)n FROM post_daily_view_sources WHERE day>=date('now','-29 days') GROUP BY post_id)x ON x.post_id=p.id LEFT JOIN(SELECT post_id,SUM(views)n FROM post_daily_views WHERE day>=date('now','-29 days') GROUP BY post_id)y ON y.post_id=p.id WHERE p.deleted_at IS NULL AND p.status='published' ORDER BY nature+studio DESC LIMIT 10").all()
 ]);
 const map=new Map();
 for(const [src,arr] of [["studio",a.results],["nature",b.results]])for(const x of arr){const row=map.get(x.day)||{day:x.day,studio:0,nature:0};row[src]=Number(x.views);map.set(x.day,row)}
 const days=[];for(let i=89;i>=0;i--){const day=new Date(Date.now()-i*86400000).toISOString().slice(0,10);days.push(map.get(day)||{day,studio:0,nature:0})}
 return {readerDaily:days,readerTop:top.results,sourceNotes:"Lượt mở trang, không phải người đọc duy nhất. Nature production chưa kích hoạt bộ đếm lượt đọc, nên số liệu Nature hiện chưa đầy đủ."};
}
const analyticsCss=".reader-report{padding:24px;margin:18px 0}.reader-head{display:flex;justify-content:space-between;flex-wrap:wrap;gap:16px}.reader-head h2{font:400 29px Georgia,serif;color:#243f32}.reader-head p{font-size:12px;color:#647766}.reader-summary{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:20px 0}.reader-summary span{display:block;font-size:11px;color:#6a7c6b}.reader-summary strong{display:block;font:400 32px Georgia,serif;color:#243f32}.reader-svg{width:100%;height:auto;max-height:280px}.reader-legend{display:flex;gap:15px;font-size:11px}.reader-rank-row{display:grid;grid-template-columns:20px minmax(0,1fr) 55px 110px;gap:10px;padding:10px 0;border-top:1px solid #e1e9dd;font-size:12px}.reader-rank-row a{color:#294d37}.reader-rank-row b,.reader-rank-row small{text-align:right}.export-toolbar{display:flex;justify-content:flex-end;margin:15px 0}@media(max-width:650px){.reader-rank-row{grid-template-columns:20px minmax(0,1fr) 45px}.reader-rank-row small{display:none}}";
export default {async fetch(request,env,ctx){
 const path=new URL(request.url).pathname;
 if(path==="/api/studio/export-word"){
  if(request.method!=="GET")return json({error:"Method not allowed"},405);
  return exportBundle(request,env,await account(request,env));
 }
 if(path==="/api/studio/dashboard"){
  const auth=await account(request,env);if(!auth)return json({error:"Unauthorized"},401);
  const response=await core.fetch(request,env,ctx);if(!response.ok)return response;
  const baseline=await response.json();const data=await readership(env);
  const days=data.readerDaily.slice(-30),studio=days.reduce((n,x)=>n+x.studio,0),nature=days.reduce((n,x)=>n+x.nature,0);
  return json({...baseline,version:"1.3.1",readerDaily:data.readerDaily,readerTop:data.readerTop,sourceNotes:data.sourceNotes,counts:{...baseline.counts,views30d:studio+nature,studio30d:studio,nature30d:nature}});
 }
 const response=await core.fetch(request,env,ctx);
 if(request.method!=="GET"||path.startsWith("/read/")||!(response.headers.get("content-type")||"").includes("text/html"))return response;
 let html=applyNatureBrand(await response.text());
 html=html.replace(OLD,NEW).replaceAll("Hương Thiền Studio","Hương Thiền Nature Studio").replaceAll("HƯƠNG THIỀN STUDIO","HƯƠNG THIỀN NATURE STUDIO").replace("<span>Hương Thiền<small>NATURE · STUDIO</small></span>","<span>Hương Thiền Nature<small>STUDIO</small></span>").replace("PHIÊN BẢN 1.1.0","PHIÊN BẢN 1.3.1").replace("</head>",'<style id="studio-editorial-131">'+analyticsCss+STUDIO_EDITORIAL_CSS+STUDIO_NATURE_CSS_V131+'</style></head>');
 const headers=new Headers(response.headers);headers.delete("content-length");headers.set("cache-control","private,no-store");
 return new Response(html,{status:response.status,headers});
}};

import studio from "./studio-api-v7.mjs";
const headers={"Cache-Control":"public,max-age=60,stale-while-revalidate=60","Content-Type":"application/json; charset=utf-8","X-Content-Type-Options":"nosniff"};
const answer=(v,status=200)=>Response.json(v,{status,headers});
const allowed=(s)=>/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(s||"");
export default {async fetch(request,env,ctx) {
  const url=new URL(request.url),p=url.pathname;
  if(request.method==="GET"&&p==="/api/public/journal"){
    const lang=url.searchParams.get("lang");
    const page=Number(url.searchParams.get("page")||1);
    const limit=Number(url.searchParams.get("limit")||50);
    if(!["vi","en"].includes(lang)||!Number.isInteger(page)||page<1||page>200||!Number.isInteger(limit)||limit<1||limit>50)return answer({error:"Invalid pagination"},400);
    try {
      const records=await env.DB.prepare("SELECT id,locale,slug,title,excerpt,category,cover_id,seo_title,seo_description,published_at,updated_at,'published' AS status FROM posts WHERE locale=? AND status='published' AND deleted_at IS NULL ORDER BY published_at DESC, id DESC LIMIT ? OFFSET ?").bind(lang,limit,(page-1)*limit).all();
      return answer({posts:records.results,page,limit});
    } catch(e){console.error("public journal list",String(e));return answer({error:"Service unavailable"},503)}
  }
  const m=p.match(/^\/api\/public\/journal\/(vi|en)\/([a-z0-9-]+)$/);
  if(request.method==="GET"&&m) {
    if(!allowed(m[2]))return answer({error:"Not found"},404);
    try {
      const article=await env.DB.prepare("SELECT id,locale,slug,title,excerpt,body,category,cover_id,seo_title,seo_description,published_at,updated_at,'published' AS status FROM posts WHERE locale=? AND slug=? AND status='published' AND deleted_at IS NULL LIMIT 1").bind(m[1],m[2]).first();
      return article?answer({post:article}):answer({error:"Not found"},404);
    }catch(e){console.error("public journal detail",String(e));return answer({error:"Service unavailable"},503)}
  }
  return studio.fetch(request,env,ctx);
}};

import existing from "./family-main-v7.mjs";
import { STUDIO_HTML } from "./studio-shell-v4.mjs";
const j=(o,status=200)=>Response.json(o,{status,headers:{"Cache-Control":"no-store","Content-Type":"application/json; charset=utf-8","X-Content-Type-Options":"nosniff"}});
const hex=bytes=>[...new Uint8Array(bytes)].map(x=>x.toString(16).padStart(2,"0")).join("");
async function account(req,env){
 const match=(req.headers.get("Cookie")||"").match(/(?:^|;\s*)ht_blog_session=([0-9a-f]{64})/);
 if(!match)return null;
 const h=hex(await crypto.subtle.digest("SHA-256",new TextEncoder().encode(match[1])));
 return env.DB.prepare("SELECT u.id,u.email,u.display_name,u.role FROM users u JOIN sessions s ON s.user_id=u.id WHERE s.token_hash=? AND s.expires_at>datetime('now')").bind(h).first();
}
async function dashboard(env){
 const queries=[
  env.DB.prepare("SELECT status,workflow_stage,category,locale,created_at,updated_at,published_at,deleted_at FROM posts").all(),
  env.DB.prepare("SELECT COUNT(*) n,COALESCE(SUM(byte_size),0) bytes FROM media").first(),
  env.DB.prepare("SELECT action,created_at,target_id FROM audit_log ORDER BY id DESC LIMIT 8").all(),
  env.DB.prepare("SELECT day, SUM(views) total FROM post_daily_views WHERE day>=date('now','-29 days') GROUP BY day ORDER BY day").all(),
  env.DB.prepare("SELECT p.id,p.title,p.locale,COALESCE(SUM(v.views),0) views FROM posts p LEFT JOIN post_daily_views v ON v.post_id=p.id WHERE p.deleted_at IS NULL AND p.status='published' GROUP BY p.id ORDER BY views DESC LIMIT 5").all()
 ];
 const [posts,media,events,views,top]=await Promise.all(queries);
 const active=posts.results.filter(p=>!p.deleted_at);
 const bucket={idea:0,writing:0,review:0,published:0};
 for(const p of active)bucket[p.status==='published'?'published':p.workflow_stage in bucket?p.workflow_stage:'writing']++;
 const cats={};for(const p of active)cats[p.category]=(cats[p.category]||0)+1;
 const chart=[];for(let i=13;i>=0;i--){const d=new Date(Date.now()-i*86400000).toISOString().slice(0,10);chart.push({day:d,published:active.filter(p=>p.status==='published'&&String(p.published_at||'').slice(0,10)===d).length,edited:active.filter(p=>String(p.updated_at||'').slice(0,10)===d).length})}
 return j({version:"1.1.0",counts:{total:active.length,published:bucket.published,draft:active.length-bucket.published,trash:posts.results.length-active.length,media:media.n,mediaBytes:media.bytes,views30d:views.results.reduce((a,v)=>a+v.total,0)},pipeline:bucket,categories:cats,chart,views:views.results,topPosts:top.results,activity:events.results,notes:"Lượt mở bài là số lần tải trang /read/ trong CMS, không phải số người đọc duy nhất. Chưa bao gồm lượt đọc ngoài website Astro."});
}
async function getPostStages(env){
 const x=await env.DB.prepare("SELECT id,workflow_stage FROM posts").all();
 return Object.fromEntries(x.results.map(row=>[row.id,row.workflow_stage]));
}
const pageHeaders={"Content-Type":"text/html; charset=utf-8","Cache-Control":"no-store","X-Content-Type-Options":"nosniff","Referrer-Policy":"no-referrer","X-Frame-Options":"DENY","Strict-Transport-Security":"max-age=31536000","Content-Security-Policy":"default-src 'none'; connect-src 'self'; img-src 'self' data: https:; script-src 'unsafe-inline'; style-src 'unsafe-inline'; font-src 'self'; base-uri 'none'; form-action 'self'; frame-ancestors 'none'"};
export default {async fetch(request,env,ctx){
 try{
  const url=new URL(request.url),path=url.pathname,method=request.method;
  if(method==="GET"&&["/","/login"].includes(path)){
   const owner=await env.DB.prepare("SELECT COUNT(*) n FROM users WHERE role='owner'").first();
   if(owner.n===0)return Response.redirect(url.origin+"/owner-setup",302);
   return new Response(STUDIO_HTML,{headers:pageHeaders});
  }
  if(method==="GET"&&path==="/api/health")return j({ok:true,version:"1.1.0",platform:"Cloudflare Workers + D1 + R2"});
  if(method==="GET"&&path==="/api/studio/dashboard"){
   if(!await account(request,env))return j({error:"Vui lòng đăng nhập."},401);
   return dashboard(env);
  }

  if(method==="GET"&&path==="/api/studio/post-stats"){
   if(!await account(request,env))return j({error:"Vui lòng đăng nhập."},401);
   const id=url.searchParams.get("id");
   if(!/^[0-9a-f-]{36}$/.test(String(id||"")))return j({error:"Mã bài viết không hợp lệ."},400);
   const post=await env.DB.prepare("SELECT id,status,updated_at FROM posts WHERE id=? AND deleted_at IS NULL").bind(id).first();
   if(!post)return j({error:"Bài viết không tồn tại."},404);
   const stats=await env.DB.prepare("SELECT COALESCE(SUM(views),0) total,COALESCE(SUM(CASE WHEN day>=date('now','-29 days') THEN views ELSE 0 END),0) last30 FROM post_daily_views WHERE post_id=?").bind(id).first();
   return j({id:post.id,status:post.status,updated_at:post.updated_at,viewsTotal:stats?.total||0,views30d:stats?.last30||0});
  }
  if(method==="POST"&&path==="/api/studio/stage"){
   if(request.headers.get("Origin")!==url.origin)return j({error:"Nguồn yêu cầu không hợp lệ."},403);
   const user=await account(request,env);
   if(!user)return j({error:"Phiên đăng nhập hết hạn."},401);
   let body;try{body=await request.json()}catch{return j({error:"Dữ liệu không hợp lệ."},400)}
   if(!/^[0-9a-f-]{36}$/.test(String(body.id||""))||!["idea","writing","review","published"].includes(body.stage))return j({error:"Giai đoạn không hợp lệ."},400);
   const found=await env.DB.prepare("SELECT id,status,workflow_stage,deleted_at,body FROM posts WHERE id=?").bind(body.id).first();
   if(!found||found.deleted_at)return j({error:"Bài viết không tồn tại."},404);
   if(body.stage==="published"&&!String(found.body||"").trim())return j({error:"Không thể xuất bản bài viết trống."},400);
   if(body.stage==="published"){
    await env.DB.prepare("UPDATE posts SET workflow_stage='published',status='published',published_at=COALESCE(published_at,CURRENT_TIMESTAMP),updated_at=CURRENT_TIMESTAMP WHERE id=?").bind(body.id).run();
   }else{
    await env.DB.prepare("UPDATE posts SET workflow_stage=?,status='draft',published_at=NULL,updated_at=CURRENT_TIMESTAMP WHERE id=?").bind(body.stage,body.id).run();
   }
   await env.DB.prepare("INSERT INTO audit_log(user_id,action,target_id) VALUES(?,'stage_change',?)").bind(user.id,body.id).run();
   return j({ok:true,id:body.id,stage:body.stage});
  }
  if(method==="GET"&&path==="/api/posts"){
   const core=await existing.fetch(request,env,ctx);if(!core.ok)return core;
   const obj=await core.json(),stages=await getPostStages(env);
   obj.posts=obj.posts.map(p=>({...p,workflow_stage:p.status==='published'?'published':stages[p.id]||'writing'}));
   return j(obj);
  }
  if(method==="POST"&&path==="/api/posts"){
   const incoming=await request.clone().json().catch(()=>null);
   if(incoming?.status==="published"&&!String(incoming?.body||"").trim())return j({error:"Thêm nội dung trước khi xuất bản."},400);
   const core=await existing.fetch(request,env,ctx);
   if(core.ok){
    const clone=core.clone();const data=await clone.json();
    if(data.post?.id){
     if(data.post.status==="published")await env.DB.prepare("UPDATE posts SET workflow_stage='published' WHERE id=?").bind(data.post.id).run();
     else await env.DB.prepare("UPDATE posts SET workflow_stage='writing' WHERE id=? AND workflow_stage='published'").bind(data.post.id).run();
    }
   }
   return core;
  }
  if(method==="GET"&&path.startsWith("/read/")){
   const response=await existing.fetch(request,env,ctx);
   if(response.ok&&response.headers.get("content-type")?.includes("text/html")){
    const m=path.match(/^\/read\/(vi|en)\/([a-z0-9-]+)$/);
    if(m){
     const write=async()=>{const post=await env.DB.prepare("SELECT id FROM posts WHERE locale=? AND slug=? AND status='published' AND deleted_at IS NULL").bind(m[1],m[2]).first();if(post)await env.DB.prepare("INSERT INTO post_daily_views(post_id,day,views) VALUES(?,date('now'),1) ON CONFLICT(post_id,day) DO UPDATE SET views=views+1").bind(post.id).run()};
     const agent=(request.headers.get("User-Agent")||"").toLowerCase();
     if(!/bot|crawl|spider|monitor|facebookexternalhit|preview/.test(agent)){if(ctx?.waitUntil)ctx.waitUntil(write().catch(e=>console.error("view tally",e)));else await write().catch(()=>{})}
    }
   }
   return response;
  }
  return existing.fetch(request,env,ctx);
 }catch(e){console.error("Studio v1",String(e));return j({error:"Không thể xử lý yêu cầu. Vui lòng tải lại."},500)}
}};

import {STUDIO_CSS_V3} from "./studio-css-v3.mjs";
import {STUDIO_JS} from "./studio-client-v6.mjs";
export const STUDIO_HTML='<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><meta name="theme-color" content="#f6f8f3"><title>Hương Thiền Studio · Bảng quản trị nội dung</title><style>'+STUDIO_CSS_V3+'</style></head><body><section id="signin" class="auth card" hidden><div class="logo"><span class="leaf">✺</span><span>Hương Thiền<small>BLOG STUDIO</small></span></div><h1>Chào mừng trở lại</h1><p>Một không gian yên tĩnh dành cho ý tưởng và những câu chuyện.</p><form id="login-form"><label>Email<input id="email" type="email" autocomplete="email" required placeholder="your@email.com"></label><label>Mật khẩu<div style="display:flex;align-items:center;gap:6px;margin-top:8px"><input style="margin:0;flex:1" id="password" type="password" autocomplete="current-password" required><button class="btn small" id="login-eye" type="button" aria-label="Hiện mật khẩu">◉</button></div></label><p id="login-error" style="color:#b45746" role="alert"></p><button class="btn primary" id="login-submit" type="submit">Đăng nhập Studio →</button></form><div class="authlinks"><a href="/register">Đăng ký</a><a href="/forgot-password">Quên mật khẩu?</a></div></section><div id="studio" class="app" hidden><aside class="sidebar" id="sidebar"><div class="logo"><span class="leaf">✺</span><span>Hương Thiền<small>BLOG STUDIO</small></span></div><div><div class="side-group">KHÔNG GIAN LÀM VIỆC</div><button class="nav active" data-view="dashboard"><span class="symbol">▦</span>Tổng quan</button><button class="nav" data-view="posts"><span class="symbol">☷</span>Bài viết</button><button class="nav" data-view="media"><span class="symbol">▧</span>Kho ảnh</button><div class="side-group">HỆ THỐNG</div><button class="nav" data-view="changelog"><span class="symbol">◷</span>Nhật ký cập nhật</button><button class="nav" data-view="account"><span class="symbol">⚙</span>Tài khoản</button></div><div class="side-foot"><small>PHIÊN BẢN 1.1.0 · CLOUDFLARE</small><div class="userchip"><b id="profile-letter">S</b><span id="profile-name">Quản trị viên</span></div></div></aside><main class="main"><header class="topbar"><div style="display:flex;align-items:center;gap:12px"><button class="btn mobile-menu" id="mobile-menu" aria-label="Mở menu">☰</button><div class="crumb">HƯƠNG THIỀN STUDIO &nbsp; / &nbsp; <b id="crumb">Tổng quan</b></div></div><div class="actions"><a href="https://huongthiennature.com" target="_blank" rel="noopener noreferrer" class="btn ghost">↗ Website chính</a><button class="btn primary" id="new-post">＋ Bài viết mới</button><button class="btn ghost" id="logout">Đăng xuất</button></div></header><div id="content" class="content"></div><div id="editorframe" class="editorwrap" hidden></div></main></div><div class="toast" id="toast" role="status" aria-live="polite" hidden></div><script>'+STUDIO_JS+'</script></body></html>';

import {STUDIO_CSS_V2} from "./studio-css-v2.mjs";
