import {STUDIO_CSS} from "./studio-css-v1.mjs";
export const STUDIO_CSS_V2 = STUDIO_CSS + "
/* v1.1.0 — Publii-inspired distraction-free editor, independent design */
body.editor-mode{background:#fff}
body.editor-mode #sidebar{display:none}
body.editor-mode .main{width:100%}
body.editor-mode .topbar{display:none}
body.editor-mode #editorframe{padding:0 18px 72px;max-width:none;background:#fff;min-height:100vh}
body.editor-mode #editorframe .editorbar{position:sticky;top:0;z-index:56;margin:0 -18px;padding:15px clamp(18px,3.8vw,56px);background:#fffffff5;backdrop-filter:blur(14px);border-bottom:1px solid #e8eee9;min-height:76px;gap:16px;flex-wrap:wrap}
.editorbar .editor-start,.editorbar .editor-actions{display:flex;align-items:center;gap:10px;flex-wrap:wrap}
.editorbar .editor-start{min-width:0}
