function inlineToVisual(text){
 let s=esc(text);
 s=s.replace(/\[([^\]]{1,120})\]\((https?:\/\/[^\s()]{1,700})\)/g,(_,label,url)=>'<a href="'+url+'" target="_blank" rel="noopener noreferrer">'+label+'</a>');
 s=s.replace(/\*\*(.+?)\*\*/g,"<strong>$1</strong>").replace(/\*([^*]+)\*/g,"<em>$1</em>");
 return s;
}
function markdownToVisual(src){
 return String(src||"").split(/\r?\n/).map(line=>{
  if(/^!\[([^\]]*)\]\(\/media\/([0-9a-f-]{36})\)$/.test(line)){const p=line.match(/^!\[([^\]]*)\]\(\/media\/([0-9a-f-]{36})\)$/);return '<p><img alt="'+esc(p[1])+'" src="/media/'+p[2]+'" loading="lazy"></p>'}
  if(line.startsWith("### "))return "<h3>"+inlineToVisual(line.slice(4))+"</h3>";
  if(line.startsWith("## ")||line.startsWith("# "))return "<h2>"+inlineToVisual(line.replace(/^#{1,2}\s/,""))+"</h2>";
  if(line.startsWith("> "))return "<blockquote>"+inlineToVisual(line.slice(2))+"</blockquote>";
  if(line.startsWith("- "))return "<p>• "+inlineToVisual(line.slice(2))+"</p>";
  if(line.trim()==="---")return "<hr>";
  return "<p>"+(line.trim()?inlineToVisual(line):"<br>")+"</p>";
 }).join("");
}
function visualToMarkdown(root){
 function inline(n){
  if(n.nodeType===3)return n.nodeValue||"";
  if(n.nodeType!==1)return "";
  const tag=n.tagName,child=[...n.childNodes].map(inline).join("");
  if(tag==="BR")return "";
  if(tag==="STRONG"||tag==="B")return "**"+child+"**";
  if(tag==="EM"||tag==="I")return "*"+child+"*";
  if(tag==="IMG"){
    const path=n.getAttribute("src")||"";
    if(/^\/media\/[0-9a-f-]{36}$/.test(path))return "!["+(n.getAttribute("alt")||"Ảnh minh họa").replace(/\]/g,"")+"]("+path+")";
    return "";
  }
  if(tag==="A"){
    const href=n.getAttribute("href")||"";
    if(/^https?:\/\/[^\s)]+$/.test(href))return "["+child.replace(/\]/g,"")+"]("+href+")";
  }
  if(tag==="HR")return "---";
  return child;
 }
 function blocks(node){
  const result=[];
  for(const n of node.childNodes){
   if(n.nodeType===3){if(n.nodeValue?.trim())result.push(n.nodeValue);continue}
   if(n.nodeType!==1)continue;
   const tag=n.tagName;
   if(tag==="HR"){result.push("---");continue}
   if(tag==="UL"||tag==="OL"){[...n.children].forEach(li=>result.push("- "+[...li.childNodes].map(inline).join("")));continue}
   const words=[...n.childNodes].map(inline).join("").trim();
   if(tag==="H2")result.push("## "+words);
   else if(tag==="H3")result.push("### "+words);
   else if(tag==="BLOCKQUOTE")result.push("> "+words);
   else if(["P","DIV"].includes(tag))result.push(words);
   else result.push(inline(n));
  }
  return result.join("\n").trim();
 }
 return blocks(root);
}
