#signin .authlinks a{color:var(--forest);text-decoration:underline;text-underline-offset:4px}
body:has(.box > .brand){background:linear-gradient(120deg,#e8ebdf,#faf8f1 60%,#f2eedf)}
body .box{position:relative;isolation:isolate;border-radius:5px;background:#fffef9;color:var(--forest);border:1px solid rgba(36,63,50,.17);box-shadow:0 12px 50px rgba(36,63,50,.08)}
body .box:before{content:"";position:absolute;z-index:-1;top:-32px;right:-24px;background:url("https://huongthiennature.com/media/botanical-sprig.svg") center/contain no-repeat;width:104px;height:160px;opacity:.17;pointer-events:none}
body .box .brand{display:flex;align-items:center;gap:13px;font:400 25px/1.15 var(--serif);color:var(--forest)}
body .box .brand small{display:block;font:650 9px/1.5 var(--sans);letter-spacing:.2em;margin:6px 0 0;color:var(--moss)}
body .box .nature-brand-icon{width:49px;height:49px}
body .box h1{font:400 clamp(32px,5vw,43px)/1.13 var(--serif);letter-spacing:-.04em;color:var(--forest)}
body .box input{border-radius:3px;color:var(--forest);background:#fff;border-color:rgba(36,63,50,.2)}
body .box button{border-radius:3px;background:var(--forest);color:var(--paper)}
body .box button.secondary{background:var(--sage);color:var(--forest)}
body .box .password-control button{background:transparent;color:var(--forest)}
