export function applyNatureBrand(html) {
  let updated=String(html).replaceAll('<span class="leaf">✺</span>',"<img class="nature-brand-icon" src="https://huongthiennature.com/media/huong-thien-logo-forest.webp" width="43" height="43" alt="Logo Hương Thiền Nature" decoding="async">");
  updated=updated.replace(/<div class="brand">✺ Hương Thiền<small>[^<]*</small></div>/,"<div class="brand"><img class="nature-brand-icon" src="https://huongthiennature.com/media/huong-thien-logo-forest.webp" width="43" height="43" alt="Logo Hương Thiền Nature" decoding="async"><span>Hương Thiền<small>NATURE · STUDIO</small></span></div>");
  updated=updated.replace('<meta name="theme-color" content="#f6f8f3">','<meta name="theme-color" content="#243f32">');
  updated=updated.replace('</head>','<link rel="icon" href="https://huongthiennature.com/media/huong-thien-logo-forest.webp" type="image/webp"><style id="nature-brand-theme">'+BRAND_CSS+'</style></head>');
  return updated;
}
